    float StartPos[3], EndPos[3]; long LifeTimer; float Radius;
    void OnInitialActivate() { LifeTimer = -1; }
};
int main()
{
    CTCDPhysicalObstruction o = { { 1, 2, 3 }, { 4, 5, 6 }, 300, 2.5f };
